import java.util.*;

public class Solution {
    static int[] distancias(int n, int[][] arestas, int[][] consultas) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : arestas) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int LOG = 1;
        while ((1 << LOG) < n) LOG++;
        int[][] up = new int[LOG + 1][n];
        int[] prof = new int[n];
        boolean[] visto = new boolean[n];
        ArrayDeque<Integer> fila = new ArrayDeque<>();
        fila.add(0);
        visto[0] = true;
        while (!fila.isEmpty()) { // BFS: pai e profundidade sem recursão
            int u = fila.poll();
            for (int v : adj.get(u)) if (!visto[v]) {
                visto[v] = true;
                up[0][v] = u;
                prof[v] = prof[u] + 1;
                fila.add(v);
            }
        }
        for (int k = 1; k <= LOG; k++) for (int v = 0; v < n; v++) up[k][v] = up[k - 1][up[k - 1][v]];
        int[] out = new int[consultas.length];
        for (int q = 0; q < consultas.length; q++) {
            int a = consultas[q][0], b = consultas[q][1];
            out[q] = prof[a] + prof[b] - 2 * prof[lca(a, b, up, prof, LOG)];
        }
        return out;
    }

    private static int lca(int a, int b, int[][] up, int[] prof, int LOG) {
        if (prof[a] < prof[b]) { int t = a; a = b; b = t; }
        int dif = prof[a] - prof[b];
        for (int k = 0; dif > 0; k++, dif >>= 1) if ((dif & 1) == 1) a = up[k][a];
        if (a == b) return a;
        for (int k = LOG; k >= 0; k--) {
            if (up[k][a] != up[k][b]) { // só salta se ainda não chegou ao ancestral comum
                a = up[k][a];
                b = up[k][b];
            }
        }
        return up[0][a];
    }
}

