import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void pequena() {
        //        0
        //      1   2
        //     3 4   5
        //    6
        int[][] e = {{0, 1}, {0, 2}, {1, 3}, {1, 4}, {2, 5}, {3, 6}};
        int[][] q = {{6, 4}, {6, 5}, {3, 3}, {0, 6}, {4, 5}};
        assertArrayEquals(new int[]{3, 5, 0, 3, 4}, Solution.distancias(7, e, q));
    }

    @Test void umNo() {
        assertArrayEquals(new int[]{0}, Solution.distancias(1, new int[][]{}, new int[][]{{0, 0}}));
    }

    @Test void linhaGigante() {
        int n = 100_000;
        int[][] e = new int[n - 1][];
        for (int i = 0; i + 1 < n; i++) e[i] = new int[]{i, i + 1};
        int[][] q = new int[100_000][];
        var rnd = new Random(15);
        for (int i = 0; i < q.length; i++) q[i] = new int[]{rnd.nextInt(n), rnd.nextInt(n)};
        int[] r = Solution.distancias(n, e, q);
        for (int i = 0; i < q.length; i++) assertEquals(Math.abs(q[i][0] - q[i][1]), r[i]);
    }

    @Test void aleatoriaContraBruta() {
        var rnd = new Random(16);
        int n = 300;
        int[] pai = new int[n];
        int[][] e = new int[n - 1][];
        for (int v = 1; v < n; v++) { pai[v] = rnd.nextInt(v); e[v - 1] = new int[]{v, pai[v]}; }
        int[][] q = new int[500][];
        for (int i = 0; i < q.length; i++) q[i] = new int[]{rnd.nextInt(n), rnd.nextInt(n)};
        int[] r = Solution.distancias(n, e, q);
        for (int i = 0; i < q.length; i++) {
            Map<Integer, Integer> anc = new HashMap<>();
            int d = 0;
            for (int v = q[i][0]; ; v = pai[v]) { anc.put(v, d++); if (v == 0) break; }
            d = 0;
            int v = q[i][1];
            while (!anc.containsKey(v)) { v = pai[v]; d++; }
            assertEquals(d + anc.get(v), r[i]);
        }
    }
}
